NAT = [
    dict(id='NAT-1', sev='HIGH', lane='NAT', proof='Re-checked',
         title='The iOS privacy manifest declares no required-reason API, but the app\'s own Swift uses `UserDefaults`: the first TestFlight upload is refused',
         where='`ios/App/App/TkNativePlugin.swift:24,30`; `ios/App/App/PrivacyInfo.xcprivacy:5` (comment "No required-reason API is used") and `:112-113` (empty `NSPrivacyAccessedAPITypes`).',
         what='Closed in the ledger (OPS-10), still broken: the renderer-exit fix (OPS-03) added `UserDefaults` after the manifest was written, although both work items carry the warning themselves. `UserDefaults` is on Apple\'s required-reason list; an upload without the declaration is flagged ITMS-91053. The owner would meet this on the very first run of a workflow that has never run.',
         fix='Add `NSPrivacyAccessedAPICategoryUserDefaults` with reason `CA92.1`; add a test that greps the app\'s Swift for required-reason APIs and demands a matching entry.',
         checked='Both files read by the auditor and again by the lead. Not verified: how App Store Connect treats the upload today.'),
    dict(id='NAT-2', sev='MEDIUM', lane='NAT', proof='Re-checked',
         title='The gate that should tell players with an old Android System WebView to update does not work',
         where='`capacitor.config.ts:26-27` (`minWebViewVersion: 80` with no `server.errorPath`); `src/backend/pwa/boot.js:135-138` (the syntax probe uses `new Function`); `tools/release/csp.mjs:28` (no `unsafe-eval`).',
         what='Recorded as fixed (device finding F12), both halves fail. Capacitor shows an update page only when `server.errorPath` is set; otherwise it logs and loads the app anyway. And since the content-security policy was added, `new Function` throws `EvalError`, which the probe deliberately ignores, so it can no longer detect anything in any production build. A phone on WebView 61 to 79 gets "Couldn\'t load Kagemura. Check your connection" with a Retry that loops forever.',
         fix='Set `server.errorPath` to a small old-syntax page that names Android System WebView, or probe without `eval`. Correct the config comment and the F12 record.',
         checked='Capacitor\'s `Bridge.java`, the guard and the built `dist/index.html` (policy without `unsafe-eval` ahead of the guard), confirmed by the lead. Not run on an old WebView.'),
    dict(id='NAT-3', sev='MEDIUM', lane='NAT', proof='Read',
         title='A dead WebView renderer rebuilds the Android activity at once, every time, with no limit: a renderer that crashes at start loops forever',
         where='`android/app/src/main/java/com/toadstoolkingdoms/app/MainActivity.java:27-39` (`recreate()`); `TkBillingPlugin.java:61-67` (no `endConnection`).',
         what='The fix for renderer death (OPS-03) has no back-off, no count and no foreground check. If the renderer crashes during start-up on some chipset, the player sees the splash restart without end and never an error; because the process no longer dies, Play\'s crash statistics do not show it either. A renderer killed in the background is rebuilt immediately, taking back the memory Android just reclaimed. Each rebuild leaks a billing client.',
         fix='When not in the foreground, rebuild on the next `onStart`. After three rebuilds in a minute show a native "could not start" view or let the process die. Close the billing client in `handleOnDestroy`.',
         checked='The Java sources and Capacitor\'s client code. Not run on a device.'),
    dict(id='NAT-4', sev='MEDIUM', lane='NAT', proof='Re-checked',
         title='`getBridge()` is used without a null check: when Android cannot create a WebView the app crashes at launch instead of showing Capacitor\'s notice',
         where='`MainActivity.java:27`.',
         what='When the WebView package is missing, disabled or being updated by Google Play (a well-known Android failure class), Capacitor shows a "no WebView" screen and leaves the bridge null. This line, added to reduce crashes, then throws a `NullPointerException` in `onCreate`: a launch crash in Play vitals.',
         fix='`if (getBridge() == null) return;` before adding the listener.',
         checked='`MainActivity.java` and Capacitor\'s `BridgeActivity.java:27-32`, confirmed by the lead.'),
    dict(id='NAT-5', sev='LOW', lane='NAT', proof='Read',
         title='WebView 80 to 87 passes every gate, but the bundle needs 85 for JavaScript and 87 to 88 for CSS',
         where='`src/presentation/ui/groveUi.ts:209` (`replaceAll`); `src/presentation/ui/styles.css:973-1016` (`:is()`), `:127,145` (`padding-inline`); `boot.js:186` (`inset`).',
         what='An earlier audit recorded the browser surface as "Chrome 80 safe"; these uses are later or were missed. On WebView 80 to 84 the offline Alliance panel throws; up to 87 chips lose padding, non-Latin line-height rules are dropped whole, and the guard\'s own error overlay does not cover the screen.',
         fix='Raise the floor to 88 together with NAT-2, or polyfill `replaceAll` and avoid `:is()` and the logical shorthands.',
         checked='grep of `src/` and of the built assets.'),
    dict(id='NAT-6', sev='LOW', lane='NAT', proof='Read',
         title='The Android memory warning waits for signals that Android 14 and later no longer send',
         where='`MainActivity.java:48-54` (`onTrimMemory`).',
         what='Recorded as fixed (F19). On a new 2 to 3 GB phone, memory pressure during play sends no warning to the game; the renderer is killed instead, and then NAT-3 applies.',
         fix='Also override `onLowMemory()` and poll `ActivityManager.getMemoryInfo().lowMemory` on a slow timer while resumed.',
         checked='The Java source against the platform documentation as the auditor recalled it; not observed on a device.'),
    dict(id='NAT-7', sev='LOW', lane='NAT', proof='Read',
         title='The iOS sign-in token survives deleting the app: a reinstall is silently signed in to the old account',
         where='`ios/App/App/TkSecureStorePlugin.swift:59-63`; `src/backend/platform/secureTokens.ts:26-37`.',
         what='iOS keeps Keychain items when an app is deleted. A player who deleted the game to start over, or the next user of a phone handed on without a reset, gets the previous account: name, friends, Gang, purchase history and the delete-account button. Android removes everything, and the planned device test (SAV-15) expects a fresh village.',
         fix='Keep a first-run flag in `UserDefaults` (removed with the app); when absent, clear the Keychain service before reading it. Or record the automatic restore as a decision and correct the test.',
         checked='The Swift plugin and its caller. Not run on a device.'),
    dict(id='NAT-8', sev='LOW', lane='NAT', proof='Read',
         title='Android reminders show the system "(i)" icon instead of the game\'s mark',
         where='`capacitor.config.ts:30-32` (no `smallIcon`); no notification drawable under `android/app/src/main/res`.',
         what='Every reminder and server push appears in the status bar and shade with a generic glyph.',
         fix='Add a single-colour `ic_stat_kagemura` drawable, set `plugins.LocalNotifications.smallIcon` and the Firebase default icon.',
         checked='The plugin\'s fallback in `LocalNotificationManager.kt:490-498`.'),
]

